SELECT COUNT(DISTINCT session) FROM (
  SELECT session
  FROM read_log
  WHERE url = '/regist/input'
    AND session IN (
      SELECT session
      FROM read_log
      WHERE url = '/regist/confirm'
    )
);

SELECT COUNT(DISTINCT session) FROM (
  SELECT session
  FROM read_log
  WHERE action = '/regist/input'
    AND session IN (
      SELECT session
      FROM read_log
      WHERE action = '/regist/confirm'
    )
);
